bool CypressEzUsbUpdater::createCommLink()
{
	bool deviceOpen = true;
	Debug::trace(HobString("EZUSB"), HobString("createCommLink: try to open device"));
	
	newhandle = UsbManager::getInstance()->OpenDevice(usbNodeId);
    
	if(newhandle == INVALID_HANDLE_VALUE)
    {
        Debug::trace("EZUSB", HobString("createCommLink: failed to open device "));
        deviceOpen = false;
    }

    return deviceOpen;
}

// Download the bootstrap loader to device internal RAM. The bootstrap
// loader supports various bootloader features such as downloading code
// to device external RAM.  The device is held in reset during this
// download, and is released once the download is complete.
bool CypressEzUsbUpdater::initializePeripheral()
{
    bool rv = false;
    STATUS status;

    Debug::trace(HobString("EZUSB"), HobString("initializePeripheral"));

    // assert the device's 8051 CPU reset
    status = Ezusb_8051Reset(1);
    if (status == OK)
    {
        IntelHexParser ihp(BootstrapLoaderHexFile.c_str());
        status = Ezusb_DownloadIntelHex(ihp);
        if (status == OK)
        {
            // release the device's 8051 CPU reset
            // allowing the bootstrap loader to run
            status = Ezusb_8051Reset(0);
            if (status == OK)
            {
                Debug::trace(HobString("EZUSB"), HobString("initializePeripheral: bootstrap downloaded"));
                rv = true;
            }
            else
            {
                Debug::trace(HobString("EZUSB"), HobString("initializePeripheral: release device reset failed"));
            }
        }
        else
        {
            Debug::trace(HobString("EZUSB"), HobString("initializePeripheral: bootstrap hex download failed"));
        }
    }
    else
    {
        Debug::trace(HobString("EZUSB"), HobString("initializePeripheral: assert device reset failed"));
    }
    return rv;
}

